import {z} from 'zod';
import {AUTO_RATE} from '@/lib/api/gst';
import {field} from './fieldRules';

// Same labels and rules as backend/src/validations/catalog.validation.ts.
// The SKU is generated by the backend, so it is not part of the form.

const text = (label: string, max: number) =>
  field({label, kind: 'text', max, required: false});
const optionalPrice = (label: string) =>
  field({label, kind: 'price', required: false});

const variant = z.object({
  id: z.string().optional(),
  variantName: field({label: 'Variant', kind: 'text', max: 60}),
  finish: field({label: 'Finish', kind: 'text', max: 60}),
  mrp: optionalPrice('Variant MRP'),
  sellingPrice: optionalPrice('Variant Price'),
  wholesalePrice: optionalPrice('Variant Wholesale'),
  isActive: z.boolean(),
  // Shown in the table only; not sent
  available: z.number().optional(),
});

export const productSchema = z
  .object({
    name: field({label: 'Product Name', kind: 'text', max: 120}),
    categoryId: z.string().min(1, 'Category is required'),
    shopId: z.string().min(1, 'Branch is required'),
    brandId: z.string().optional(),
    productKind: z.enum(['FINISHED_GOOD', 'RAW_MATERIAL', 'HARDWARE', 'SERVICE']),
    productType: text('Product Type', 60),
    roomType: text('Room', 40),
    material: text('Material', 60),
    finish: text('Finish', 60),
    colour: text('Colour', 40),
    warrantyMonths: field({label: 'Warranty (months)', kind: 'quantity', required: false}),
    warrantyTerms: text('Warranty Terms', 500),
    assemblyRequired: z.boolean(),
    installationAvailable: z.boolean(),
    isCustomizable: z.boolean(),
    wholesalePrice: optionalPrice('Wholesale Price'),
    purchasePrice: optionalPrice('Purchase Cost'),
    mrp: field({label: 'MRP', kind: 'price'}),
    sellingPrice: field({label: 'Selling Price', kind: 'price'}),
    // 'AUTO' = the shop's GST rule (D-18), else a fixed rate such as '5'
    taxRate: z.string(),
    hsnCode: z
      .string()
      .trim()
      .min(1, 'HSN Code is required')
      .regex(/^(\d{4}|\d{6}|\d{8})$/, 'HSN Code must be 4, 6 or 8 digits'),
    careInstructions: text('Care Instructions', 300),
    shortDesc: text('Short Description', 300),
    detailedDesc: text('Detailed Description', 4000),
    tagsText: z.string().max(500).optional(),
    weightKg: z
      .union([z.string(), z.number()])
      .optional()
      .refine(
        (v) => v === undefined || v === '' || Number(v) > 0,
        'Weight must be more than 0',
      ),
    returnEligible: z.boolean(),
    returnPeriodDays: z.coerce
      .number()
      .int()
      .min(0)
      .max(30, 'Return Period can be at most 30 days'),
    seoTitle: text('SEO Title', 70),
    seoDesc: text('SEO Description', 160),
    variants: z
      .array(variant)
      .min(1, 'Add at least one variant'),
  })
  .superRefine((v, ctx) => {
    if (v.sellingPrice > v.mrp) {
      ctx.addIssue({
        code: 'custom',
        path: ['sellingPrice'],
        message: 'Selling Price cannot be more than MRP',
      });
    }
    const seen = new Set<string>();
    v.variants.forEach((row, i) => {
      const key = `${row.variantName.toLowerCase()}|${row.finish.toLowerCase()}`;
      if (seen.has(key)) {
        ctx.addIssue({
          code: 'custom',
          path: ['variants', i, 'variantName'],
          message: 'This variant and finish is already listed',
        });
      }
      seen.add(key);
    });
  });

export type ProductValues = z.input<typeof productSchema>;
export type ProductOutput = z.output<typeof productSchema>;

export const EMPTY_PRODUCT: ProductValues = {
  name: '',
  categoryId: '',
  shopId: '',
  brandId: '',
  productKind: 'FINISHED_GOOD',
  productType: '',
  roomType: '',
  material: '',
  finish: '',
  colour: '',
  warrantyMonths: '',
  warrantyTerms: '',
  assemblyRequired: false,
  installationAvailable: false,
  isCustomizable: false,
  wholesalePrice: '',
  purchasePrice: '',
  mrp: '',
  sellingPrice: '',
  taxRate: AUTO_RATE,
  hsnCode: '',
  careInstructions: '',
  shortDesc: '',
  detailedDesc: '',
  tagsText: '',
  weightKg: '',
  returnEligible: true,
  returnPeriodDays: 7,
  seoTitle: '',
  seoDesc: '',
  variants: [
    {
      variantName: 'Standard',
      finish: '',
      mrp: '',
      sellingPrice: '',
      wholesalePrice: '',
      isActive: true,
    },
  ],
};

/** Form values -> API body (tags as a list, empty values dropped) */
export const toProductBody = (v: ProductOutput) => {
  const {tagsText, weightKg, variants, ...rest} = v;
  return {
    ...rest,
    taxRate: rest.taxRate === AUTO_RATE ? null : Number(rest.taxRate),
    brandId: rest.brandId || undefined,
    weightKg:
      weightKg === '' || weightKg === undefined ? undefined : Number(weightKg),
    tags: (tagsText ?? '')
      .split(',')
      .map((t) => t.trim())
      .filter(Boolean),
    warrantyMonths: rest.warrantyMonths ?? 0,
    variants: variants.map(({available, ...row}) => row),
  };
};
